// ─────────────────────────────────────────────────────────────────────────────
// Feed registry
// Kept in a Code node rather than hard-coded in the RSS node so that the list
// is versioned with the workflow and one dead feed does not require rewiring
// the canvas. The RSS node below runs once per item emitted here.
// ─────────────────────────────────────────────────────────────────────────────
const FEEDS = [
  { url: 'https://feeds.a.dj.com/rss/RSSMarketsMain.xml',            desk: 'markets'  },
  { url: 'https://www.cnbc.com/id/20910258/device/rss/rss.html',     desk: 'economy'  },
  { url: 'https://www.cnbc.com/id/100003114/device/rss/rss.html',    desk: 'topnews'  },
  { url: 'https://www.marketwatch.com/rss/topstories',              desk: 'markets'  },
  { url: 'https://finance.yahoo.com/news/rssindex',                 desk: 'markets'  },
];

return FEEDS.map((feed) => ({ json: { ...feed, queued_at: new Date().toISOString() } }));

// ─────────────────────────────────────────────────────────────────────────────
// Normalise + de-duplicate
//
// n8n ships a "Remove Duplicates" node. It compares one field, exactly, within
// a single execution. A news pipeline needs four things it cannot do:
//
//   1. Field drift    — every feed names things differently (isoDate / pubDate /
//                       date; contentSnippet / content / description).
//   2. URL noise      — the same article arrives with different utm_* params,
//                       so an exact-match comparison sees two distinct URLs.
//   3. Near-duplicates— two outlets run the same story under different
//                       headlines. Exact matching never catches those.
//   4. Cross-run memory — the run six hours ago already alerted on this story.
//                       A per-execution node has no memory at all.
//
// (1)-(3) are handled below; (4) uses getWorkflowStaticData, which n8n persists
// between executions, with a rolling 72h window so it cannot grow unbounded.
//
// No require() anywhere: n8n 2.x runs Code nodes inside an isolated task runner
// where Node built-ins are not allow-listed by default, so the hash is written
// out by hand (FNV-1a).
// ─────────────────────────────────────────────────────────────────────────────

const MAX_AGE_HOURS    = 24;   // ignore anything older than this
const MAX_ITEMS        = 10;   // cap LLM spend per run
const TITLE_SIMILARITY = 0.55; // Jaccard threshold for "same story"
const MEMORY_HOURS     = 72;   // how long we remember a URL across runs

// Source reputation. The article's own hostname is authoritative — feed URLs
// syndicate, article links do not.
const SOURCES = {
  'wsj.com': ['wsj', 0.95],
  'dowjones.com': ['wsj', 0.95],
  'cnbc.com': ['cnbc', 0.85],
  'reuters.com': ['reuters', 1.0],
  'bloomberg.com': ['bloomberg', 1.0],
  'ft.com': ['ft', 0.95],
  'marketwatch.com': ['marketwatch', 0.75],
  'yahoo.com': ['yahoo_finance', 0.65],
  'investing.com': ['investing_com', 0.6],
  'seekingalpha.com': ['seeking_alpha', 0.55],
};

const STOPWORDS = new Set(('a an the and or but if then than that this these those of in on at ' +
  'to for from by with as is are was were be been being it its his her their our your my we ' +
  'you they he she has have had do does did not no nor so such over under after before about ' +
  'says say said report reports new news update updates amid amp will can could may').split(' '));

// ── helpers ────────────────────────────────────────────────────────────────
function fnv1a(str) {
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = (h + ((h << 1) + (h << 4) + (h << 7) + (h << 8) + (h << 24))) >>> 0;
  }
  return h.toString(16).padStart(8, '0');
}

// Parsed by hand rather than with `new URL()`. The n8n 2.x task runner sandbox
// does not reliably expose the WHATWG URL constructor, and when it throws every
// article silently falls back to source "unknown" (weight 0.5) — the ranking
// still "works", it just ranks everything identically. Found by running it.
const TRACKING_PARAMS = ['fbclid', 'gclid', 'mc_cid', 'mc_eid', 'ref', 'ito', 'mod', 'yptr'];

function canonicalise(rawUrl) {
  const raw = String(rawUrl || '').trim();
  const m = raw.match(/^(https?):\/\/([^/?#]+)([^?#]*)(?:\?([^#]*))?/i);
  if (!m) return { url: raw, host: '' };

  const host = m[2].toLowerCase().replace(/^www\./, '').replace(/:\d+$/, '');
  const path = (m[3] || '/').replace(/\/+$/, '') || '/';
  const query = (m[4] || '')
    .split('&')
    .filter(Boolean)
    .filter((kv) => {
      const key = kv.split('=')[0].toLowerCase();
      return !key.startsWith('utm_') && !TRACKING_PARAMS.includes(key);
    })
    .sort();

  return { url: `https://${host}${path}${query.length ? '?' + query.join('&') : ''}`, host };
}

function sourceOf(host) {
  for (const domain of Object.keys(SOURCES)) {
    if (host === domain || host.endsWith('.' + domain)) return SOURCES[domain];
  }
  return ['unknown', 0.5];
}

function tokens(text) {
  return new Set(
    String(text || '')
      .toLowerCase()
      .replace(/[^a-z0-9' ]+/g, ' ')
      .split(/\s+/)
      .filter((w) => w.length > 2 && !STOPWORDS.has(w))
  );
}

function jaccard(a, b) {
  if (!a.size || !b.size) return 0;
  let shared = 0;
  for (const t of a) if (b.has(t)) shared++;
  return shared / (a.size + b.size - shared);
}

function pickDate(row) {
  const raw = row.isoDate || row.pubDate || row.published || row.date || row.updated;
  const d = raw ? new Date(raw) : null;
  return d && !isNaN(d.getTime()) ? d : null;
}

function clean(text, limit) {
  return String(text || '')
    .replace(/<[^>]*>/g, ' ')
    .replace(/&[a-z]+;/gi, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, limit);
}

// ── 1. normalise ───────────────────────────────────────────────────────────
const now = Date.now();
const cutoff = now - MAX_AGE_HOURS * 3600 * 1000;
const normalised = [];

for (const item of $input.all()) {
  const row = item.json;
  const link = row.link || row.guid || row.id;
  if (!link || !row.title) continue;

  const { url, host } = canonicalise(link);
  const [source, weight] = sourceOf(host);
  const published = pickDate(row);
  if (published && published.getTime() < cutoff) continue;

  normalised.push({
    id: fnv1a(url),
    title: clean(row.title, 300),
    excerpt: clean(row.contentSnippet || row.content || row.description || row.summary, 700),
    url,
    host,
    source,
    source_weight: weight,
    published_at: published ? published.toISOString() : null,
    age_hours: published ? Math.round(((now - published.getTime()) / 3600000) * 10) / 10 : null,
    tokens: tokens(row.title),
  });
}

// ── 2. cross-run memory ────────────────────────────────────────────────────
let memory = {};
let memoryAvailable = true;
try {
  const staticData = $getWorkflowStaticData('global');
  staticData.seen = staticData.seen || {};
  const memCutoff = now - MEMORY_HOURS * 3600 * 1000;
  for (const [key, ts] of Object.entries(staticData.seen)) {
    if (ts >= memCutoff) memory[key] = ts;   // prune while we read
  }
  staticData.seen = memory;
} catch (e) {
  memoryAvailable = false;                    // never let dedup memory break a run
}

// ── 3. rank, then de-duplicate ─────────────────────────────────────────────
normalised.sort((a, b) => (b.source_weight - a.source_weight) || ((a.age_hours ?? 99) - (b.age_hours ?? 99)));

// ── 3a. de-duplicate (no cap yet) ──────────────────────────────────────────
const eligible = [];
const suppressed = [];   // duplicates we must also remember, see below
const stats = { fetched: $input.all().length, normalised: normalised.length, exact: 0, near: 0, seen_before: 0, capped: 0 };

for (const article of normalised) {
  if (eligible.some((k) => k.id === article.id)) { stats.exact++; suppressed.push(article.id); continue; }
  if (memoryAvailable && memory[article.id]) { stats.seen_before++; continue; }

  const twin = eligible.find((k) => k.source !== article.source && jaccard(k.tokens, article.tokens) >= TITLE_SIMILARITY);
  if (twin) { stats.near++; suppressed.push(article.id); continue; }

  eligible.push(article);
}

// ── 3b. cap round-robin across sources ─────────────────────────────────────
// Taking the top MAX_ITEMS straight off a weight-sorted list lets the single
// highest-weighted outlet that happens to publish a lot fill the entire batch —
// the first run of this pipeline returned ten CNBC articles and nothing else.
// One item per source per pass keeps the batch representative, while the pass
// order still respects source weight.
const bySource = new Map();
for (const article of eligible) {
  if (!bySource.has(article.source)) bySource.set(article.source, []);
  bySource.get(article.source).push(article);
}
const queues = [...bySource.values()].sort((a, b) => b[0].source_weight - a[0].source_weight);

const kept = [];
let drained = false;
while (kept.length < MAX_ITEMS && !drained) {
  drained = true;
  for (const queue of queues) {
    if (kept.length >= MAX_ITEMS) break;
    const next = queue.shift();
    if (next) { kept.push(next); drained = false; }
  }
}
stats.capped = eligible.length - kept.length;   // not "seen" — they retry next run

// Remember the suppressed ones too. Without this, tomorrow's run drops the WSJ
// original as "seen", finds no twin for the CNBC retelling still in the feed,
// and re-alerts on a story that was already sent.
if (memoryAvailable) for (const id of [...kept.map((a) => a.id), ...suppressed]) memory[id] = now;

console.log(`dedupe: fetched=${stats.fetched} normalised=${stats.normalised} kept=${kept.length} exact=${stats.exact} near=${stats.near} seen_before=${stats.seen_before} capped=${stats.capped} memory=${memoryAvailable} urlCtor=${typeof URL}`);
console.log('sources: ' + JSON.stringify(kept.reduce((a, k) => ({ ...a, [k.source]: (a[k.source] || 0) + 1 }), {})));

// tokens is a Set — strip it before it leaves the node.
return kept.map(({ tokens: _t, ...rest }) => ({ json: { ...rest, dedupe_stats: stats } }));

// ─────────────────────────────────────────────────────────────────────────────
// Parse the model response and re-join it to the article it came from.
//
// Two problems this solves:
//
//  a) The OpenAI node replaces the item — the article fields are gone from the
//     stream. Re-joining by item index is fragile: the moment one item takes
//     the node's error output, every index downstream is off by one. So the
//     model is asked to echo the article `id`, and the join is done on that.
//
//  b) An LLM returns JSON "usually". A pipeline that throws on the one run
//     where it wraps the object in ```json fences is a pipeline that pages you
//     at 3am. Parsing is defensive, and an unparseable response degrades to a
//     low-impact record instead of killing the execution.
// ─────────────────────────────────────────────────────────────────────────────

const CATEGORIES = ['monetary_policy', 'earnings', 'macro_data', 'geopolitics',
                    'commodities', 'crypto', 'corporate_action', 'general'];
const SENTIMENTS = ['positive', 'negative', 'neutral'];

const articles = new Map();
for (const item of $('Normalize & Deduplicate').all()) articles.set(item.json.id, item.json);

function extractContent(json) {
  const candidate = json?.message?.content ?? json?.content ?? json?.text ?? json?.output ?? json;
  if (typeof candidate !== 'string') return candidate;
  const fenced = candidate.match(/```(?:json)?\s*([\s\S]*?)```/i);
  const raw = (fenced ? fenced[1] : candidate).trim();
  try { return JSON.parse(raw); } catch (e) { /* fall through */ }
  const braced = raw.match(/\{[\s\S]*\}/);
  if (braced) { try { return JSON.parse(braced[0]); } catch (e) { /* give up */ } }
  return null;
}

const out = [];
let index = 0;

for (const item of $input.all()) {
  const parsed = extractContent(item.json);
  const article = articles.get(parsed?.id) ?? [...articles.values()][index];
  index++;
  if (!article) continue;

  const impact = Number(parsed?.impact_score);
  out.push({
    json: {
      ...article,
      summary: String(parsed?.summary ?? article.excerpt ?? '').slice(0, 600),
      category: CATEGORIES.includes(parsed?.category) ? parsed.category : 'general',
      sentiment: SENTIMENTS.includes(parsed?.sentiment) ? parsed.sentiment : 'neutral',
      impact_score: Number.isFinite(impact) ? Math.min(Math.max(impact, 0), 10) : 5,
      tickers: Array.isArray(parsed?.tickers)
        ? parsed.tickers.filter((t) => typeof t === 'string').slice(0, 10).map((t) => t.toUpperCase())
        : [],
      llm_parse_ok: parsed !== null,
    },
  });
}

console.log(`llm parse: in=${$input.all().length} out=${out.length} failed=${out.filter((o) => !o.json.llm_parse_ok).length}`);
return out;

// ─────────────────────────────────────────────────────────────────────────────
// Flatten into one row per article, shaped exactly like the Google Sheet.
// The Sheets node uses auto-map, so the field names below ARE the column
// headers — keep them in sync with the sheet, not with the internal payloads.
// Joined on client_ref, which the enrichment API echoes back verbatim.
// ─────────────────────────────────────────────────────────────────────────────

const articles = new Map();
for (const item of $('Parse LLM Output').all()) articles.set(item.json.id, item.json);

const rows = [];

for (const item of $input.all()) {
  const api = item.json;
  const article = articles.get(api.client_ref);
  if (!article) continue;

  const breakdown = api.score_breakdown ?? {};

  rows.push({
    json: {
      timestamp: new Date().toISOString(),
      id: article.id,
      published_at: article.published_at ?? '',
      age_hours: article.age_hours ?? '',
      source: article.source,
      title: article.title,
      summary: article.summary,
      category: article.category,
      sentiment: article.sentiment,
      impact_score: article.impact_score,
      entities: (api.entities ?? []).map((e) => e.symbol).join(', '),
      sectors: (api.sectors ?? []).join(', '),
      relevance_score: api.relevance_score ?? 0,
      priority: api.priority ?? 'low',
      cluster_id: api.cluster_id ?? '',
      is_followup: api.is_followup ? 'yes' : 'no',
      score_reason: api.reason ?? '',
      score_recency: breakdown.recency ?? '',
      score_novelty: breakdown.novelty ?? '',
      url: article.url,
    },
  });
}

rows.sort((a, b) => b.json.relevance_score - a.json.relevance_score);
console.log(`assembled ${rows.length} rows; high=${rows.filter((r) => r.json.priority === 'high').length}`);
return rows;

// ─────────────────────────────────────────────────────────────────────────────
// Error lane.
//
// Both the model call and the enrichment API call route their error output
// here. Each has already exhausted its retries (3 attempts, backoff) before an
// item reaches this node, so anything arriving is a real, persistent failure
// worth waking someone for — not a transient blip.
//
// The job here is to turn n8n's raw error object into something a human can
// act on from a phone: which stage, which article, what the upstream actually
// said, and whether the run produced anything at all.
// ─────────────────────────────────────────────────────────────────────────────

const failures = $input.all();
if (failures.length === 0) return [];

// n8n's error-output items do not have one fixed shape: depending on the node
// and the failure, the useful text sits at json.error.message, json.error, a
// nested response body, or nowhere at all while the item is just the input
// echoed back. The first live run of this pipeline classified ten real
// failures as "unknown" for exactly that reason — the handler was reading a
// shape that n8n does not always produce.
//
// So instead of guessing a path, walk the item and take the first thing that
// looks like a message or a status code, and keep the item's own top-level
// keys so an unfamiliar shape is visible in the alert rather than swallowed.

const MESSAGE_KEYS = ['message', 'description', 'detail', 'reason', 'errorMessage', 'error_description'];
const STATUS_KEYS = ['httpCode', 'statusCode', 'status', 'code'];
// The request target is often the only thing that says WHICH dependency broke:
// a DNS or connection error message names a host, never the workflow stage.
const TARGET_KEYS = ['url', 'uri', 'hostname', 'host', 'endpoint', 'baseURL'];

function harvest(value, depth = 0, found = { message: null, status: null, blobs: [], targets: [] }) {
  if (depth > 4 || value === null || typeof value !== 'object') return found;

  for (const [key, child] of Object.entries(value)) {
    if (!found.message && MESSAGE_KEYS.includes(key) && typeof child === 'string' && child.trim()) {
      found.message = child.trim();
    }
    if (found.status === null && STATUS_KEYS.includes(key) && (typeof child === 'number' || /^\d{3}$/.test(String(child)))) {
      found.status = Number(child);
    }
    if (TARGET_KEYS.includes(key) && typeof child === 'string' && /^https?:\/\//i.test(child)) {
      found.targets.push(child.slice(0, 200));
    }
    if (typeof child === 'string' && child.length > 40 && /error|failed|invalid|denied|timeout/i.test(child)) {
      found.blobs.push(child.slice(0, 200));
    }
    if (child && typeof child === 'object') harvest(child, depth + 1, found);
  }
  return found;
}

function describe(json) {
  const found = harvest(json?.error ?? json);
  const status = found.status;
  const message = found.message ?? found.blobs[0] ?? 'No error message on the item';

  // Match against the message, any error-ish text found, AND the request
  // target. A DNS failure reads "getaddrinfo ENOTFOUND <host>" — it names the
  // host but never the stage, so without the target the first live error-lane
  // test classified ten real failures as "unknown".
  const haystack = `${message} ${found.blobs.join(' ')} ${found.targets.join(' ')}`;
  const NETWORK = /getaddrinfo|enotfound|econnrefused|econnreset|etimedout|ehostunreach|socket hang up|network|timeout/i;

  let stage = 'unknown';
  if (/openai|gpt-|model|completion|rate limit/i.test(haystack)) stage = 'llm';
  else if (/enrich|x-api-key|market-intel/i.test(haystack)) stage = 'enrichment_api';
  else if (NETWORK.test(haystack)) stage = 'network';
  if (status === 401 || status === 403) stage = stage === 'unknown' ? 'auth' : stage;
  if (status === 429) stage = 'rate_limit';

  return {
    stage,
    status,
    message: String(message).slice(0, 400),
    // When the shape is unfamiliar the alert still says what WAS on the item,
    // which is what you actually need at 3am to fix the handler.
    shape: Object.keys(json ?? {}).slice(0, 12).join(', '),
    target: found.targets[0] ?? '',
    article: json?.title ?? json?.url ?? json?.id ?? '(no article context)',
  };
}

const details = failures.map((f) => describe(f.json));
const byStage = details.reduce((acc, d) => ({ ...acc, [d.stage]: (acc[d.stage] ?? 0) + 1 }), {});

// Was anything salvaged, or did the whole run fail? Changes how urgent this is.
let delivered = 0;
try { delivered = $('Assemble Record').all().length; } catch (e) { delivered = 0; }

const worst = details[0];
const summary = Object.entries(byStage).map(([k, v]) => `${k}×${v}`).join(', ');

console.log(`pipeline failures: ${failures.length} (${summary}); delivered=${delivered}`);

return [{
  json: {
    failed_count: failures.length,
    delivered_count: delivered,
    severity: delivered === 0 ? 'critical' : 'degraded',
    stages: summary,
    first_error_stage: worst.stage,
    first_error_status: worst.status ?? 'n/a',
    first_error_message: worst.message,
    first_error_article: worst.article,
    first_error_shape: worst.shape,
    first_error_target: worst.target,
    sample: details.slice(0, 5).map((d) => `• [${d.stage}${d.status ? ' ' + d.status : ''}] ${d.article} — ${d.message}`).join('\n'),
    workflow: $workflow.name,
    execution_url: $execution?.resumeUrl ?? '',
    execution_id: $execution?.id ?? '',
    failed_at: new Date().toISOString(),
  },
}];
